  'Bus {b} at {t}': 'אוטובוס {b} ב־{t}', 'at the station {t}': 'בתחנה {t}', 'At the station {t}': 'בתחנה {t}',
  '{n} min before the {t} train': '{n} דק׳ לפני הרכבת של {t}', 'the {t} train may leave first': 'הרכבת של {t} עלולה לצאת קודם',
